function gcd(a, b) { a = Math.abs(a); b = Math.abs(b); while (b !== 0) { const t = b; b = a % b; a = t; } return a; }

// Konversi bentuk: x = intPart + nonRepeat/10^k + repeatBlock/repeatDen
// Misal: 0.181818... => nonRepeat="" (k=0), repeat="18" => value = 18 / 99
function repeatingDecimalToFraction(intPart, nonRepeatStr, repeatStr) {
  const k = nonRepeatStr.length;
  const r = repeatStr.length;

  const nonRepeat = nonRepeatStr === "" ? 0 : parseInt(nonRepeatStr, 10);
  const repeat = parseInt(repeatStr, 10);

  // value = intPart + nonRepeat/10^k + repeat/(10^k)*(1/ (10^r-1))
  // Agar menjadi pecahan: value = intPart + (nonRepeat*(10^r-1)+repeat)/(10^k*(10^r-1))
  const denom = Math.pow(10, k) * (Math.pow(10, r) - 1);
  const numer = intPart * denom + nonRepeat * (Math.pow(10, r) - 1) + repeat;

  const g = gcd(numer, denom);
  return { numer: numer / g, denom: denom / g };
}

// Contoh: 0,181818... => intPart=0, nonRepeat="", repeat="18"
const ex1 = repeatingDecimalToFraction(0, "", "18");
console.log(`0.181818... = ${ex1.numer}/${ex1.denom}`);

// Contoh: 0,121212... => intPart=0, nonRepeat="", repeat="12"
const ex2 = repeatingDecimalToFraction(0, "", "12");
console.log(`0.121212... = ${ex2.numer}/${ex2.denom}`);

function solveAbsLe(c, r) {
  // Solusi |x-c| <= r adalah c-r <= x <= c+r jika r>=0
  if (r < 0) return { valid: false, interval: "Tidak ada solusi karena |x-c| selalu >= 0" };
  return { valid: true, interval: { left: c - r, right: c + r } };
}

const c = 3;
const r = 5;
const res = solveAbsLe(c, r);
if (res.valid) {
  console.log(`Solusi |x-${c}| <= ${r} adalah ${res.interval.left} <= x <= ${res.interval.right}`);
} else {
  console.log(res.interval);
}

